/* ══ SECTION PAGE ══ */
function DocList({items}) {
  return <ul className="doc-list">{items.map((it,i)=><li key={i}><span className="doc-check"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><polyline points="20 6 9 17 4 12"/></svg></span>{it}</li>)}</ul>;
}
function NoteBox({n}) {
  const cls = n.type==="danger"?"note-box danger":n.type==="warning"?"note-box warning":"note-box info";
  return <div className={cls}><span className="note-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"/><line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg></span>{n.text}</div>;
}
function RulesTable({items}) {
  return <div className="rules-table">{items.map((r,i)=><div className="rt-row" key={i}><div className="rt-age">{r.age}</div><div className="rt-doc">{r.docs}</div></div>)}</div>;
}
function SubGroups({subgroups}) {
  return <div className="subgroups">{subgroups.map((sg,i)=><div className="sg-card" key={i}><div className="sg-label">{sg.label}</div><DocList items={sg.items}/></div>)}</div>;
}
function SpecList({items}) {
  return <div className="spec-list">{items.map((it,i)=><div className="spec-item" key={i}><span className="spec-dot"/>{it}</div>)}</div>;
}

